package com.tracker.controller;
import com.tracker.entity.*; import com.tracker.exception.ApiException; import com.tracker.repository.CertificationRepository; import com.tracker.service.AccessService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/certifications") public class DuplicateController {private final CertificationRepository certs;private final AccessService access;public DuplicateController(CertificationRepository c,AccessService a){certs=c;access=a;}
 @GetMapping("/{id}/duplicates") public List<Map<String,Object>> duplicates(@PathVariable Long id,Authentication auth){User reviewer=access.current(auth);if(reviewer.getRole()==Role.STUDENT)throw new ApiException("Faculty access required",HttpStatus.FORBIDDEN);Certification target=certs.findById(id).orElseThrow(()->new ApiException("Certification not found",HttpStatus.NOT_FOUND));String issuer=norm(target.getIssuingOrganization()),name=norm(target.getCertificationName()),credential=norm(target.getCredentialId());return certs.findAll().stream().filter(c->!c.getId().equals(id)&&(credential!=null&&!credential.isBlank()&&credential.equals(norm(c.getCredentialId()))||issuer.equals(norm(c.getIssuingOrganization()))&&name.equals(norm(c.getCertificationName())))).map(c->Map.<String,Object>of("id",c.getId(),"student",c.getStudentName(),"status",c.getStatus().name(),"sameStudent",c.getUser().getId().equals(target.getUser().getId()),"reason",credential!=null&&!credential.isBlank()&&credential.equals(norm(c.getCredentialId()))?"Matching certificate ID":"Matching issuer and title")).toList();}
 private String norm(String x){return x==null?null:x.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+"," ");}}
